import { defineStyles } from '@/utils/defineStyles'
import { colors, useTheme } from '@/theme'
import { TextInput, TouchableOpacity, View } from 'react-native'
import { LiquidGlassSearchBar } from './LiquidGlassSearchBar'
import * as Haptics from 'expo-haptics'
import { XIcon } from 'lucide-react-native'
import { FilterButton } from './FilterButton'
import { FilterConfig, FilterState } from '@/utils/createFilterStore'

type SearchBarContainerProps<T extends string = string> = {
	searchInputRef: React.RefObject<TextInput | null>
	setIsSearchBarOpen: (isSearchBarOpen: boolean) => void
	searchValue: string
	setSearchValue: (searchValue: string) => void
	placeholder?: string
	filterConfigs?: FilterConfig<T>[]
	filterStore?: FilterState<T>
}

export function SearchBarContainer<T extends string = string>({
	searchInputRef,
	setIsSearchBarOpen,
	searchValue,
	setSearchValue,
	placeholder = 'Search',
	filterConfigs,
	filterStore
}: SearchBarContainerProps<T>) {
	const { theme } = useTheme()
	const handlePress = () => {
		Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Medium)
		setIsSearchBarOpen(true)
		setTimeout(() => {
			searchInputRef?.current?.focus()
		}, 0)
	}

	return (
		<View style={styles.searchBarContainer}>
			<TouchableOpacity
				onPress={handlePress}
				style={styles.liquidGlassButtonWrapper}
			>
				<LiquidGlassSearchBar
					setIsSearchBarOpen={setIsSearchBarOpen}
					isButton={true}
					searchValue={searchValue}
					placeholder={placeholder}
				/>
				{searchValue && (
					<TouchableOpacity
						onPress={() => setSearchValue('')}
						style={styles.clearButton}
					>
						<XIcon size={24} color={colors[theme].gray[900]} />
					</TouchableOpacity>
				)}
			</TouchableOpacity>
			{filterConfigs && filterStore && (
				<FilterButton filterConfigs={filterConfigs} filterStore={filterStore} />
			)}
		</View>
	)
}

const styles = defineStyles({
	searchBarContainer: {
		flexDirection: 'row',
		gap: 10
	},
	liquidGlassButtonWrapper: {
		flex: 1,
		flexShrink: 1
	},
	clearButton: {
		position: 'absolute',
		right: 20,
		top: 0,
		bottom: 0,
		justifyContent: 'center',
		alignItems: 'center'
	}
})
